onal</label><input class="form-control" name="station_code" maxlength="40"></div></div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary btn-operational" type="submit">Crear usuario</button></div></form></div></div></div>
